<?php
declare(strict_types=1);require_once '../config/config.php';require_once '../includes/church-book-functions.php';requireLogin();cb_require_permission('visitors.view');$conn->set_charset('utf8mb4');
$q=cb_clean($_GET['q']??'');$type=cb_clean($_GET['type']??'');$follow=cb_clean($_GET['follow']??'');$from=cb_clean($_GET['from']??'');$to=cb_clean($_GET['to']??'');$where=['1=1'];$types='';$params=[];
if($q!==''){$where[]="(v.full_name LIKE ? OR v.phone LIKE ? OR v.email LIKE ? OR v.address LIKE ? OR v.service_attended LIKE ? OR v.invited_by LIKE ?)";$like="%{$q}%";for($i=0;$i<6;$i++){$params[]=$like;$types.='s';}}if(in_array($type,['First Time','Returning'],true)){$where[]='v.visitor_type=?';$params[]=$type;$types.='s';}if(in_array($follow,['Not Required','Pending','Contacted','Completed'],true)){$where[]='v.follow_up_status=?';$params[]=$follow;$types.='s';}if($from!==''&&cb_valid_date($from)){$where[]='v.visit_date>=?';$params[]=$from;$types.='s';}if($to!==''&&cb_valid_date($to)){$where[]='v.visit_date<=?';$params[]=$to;$types.='s';}
$rows=cb_fetch_all($conn,"SELECT v.*,m.member_no FROM church_visitors v LEFT JOIN members m ON m.id=v.member_id WHERE ".implode(' AND ',$where)." ORDER BY v.visit_date DESC,v.id DESC",$types,$params);
header('Content-Type:text/csv;charset=UTF-8');header('Content-Disposition:attachment;filename="church-visitors-'.date('Y-m-d').'.csv"');$o=fopen('php://output','w');fprintf($o,chr(0xEF).chr(0xBB).chr(0xBF));fputcsv($o,['Visit Date','Full Name','Member No','Gender','Phone','Email','Address','Visitor Type','Service Attended','Invited By','Reason for Visit','Prayer Request','Follow-up Status','Assigned To','Notes']);foreach($rows as $r)fputcsv($o,[$r['visit_date'],$r['full_name'],$r['member_no'],$r['gender'],$r['phone'],$r['email'],$r['address'],$r['visitor_type'],$r['service_attended'],$r['invited_by'],$r['reason_for_visit'],$r['prayer_request'],$r['follow_up_status'],$r['assigned_to'],$r['notes']]);fclose($o);exit;
